package upgrade

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/gotcli/got/internal/generator"
)

// v020Project copies files generated by GOT with blueprints v0.2.0.
func v020Project(t *testing.T) string {
	t.Helper()
	project := t.TempDir()
	fixtures := map[string]string{
		"gitignore.txt": ".gitignore", "go.mod.txt": "go.mod", "main.go.txt": "main.go",
		"databases/pg.go.txt": "databases/pg.go", "routes/health.go.txt": "routes/health.go",
	}
	for source, target := range fixtures {
		content, err := os.ReadFile(filepath.Join("testdata", "v0.2.0", source))
		if err != nil {
			t.Fatal(err)
		}
		path := filepath.Join(project, target)
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, content, 0o644); err != nil {
			t.Fatal(err)
		}
	}
	return project
}

func statuses(results []Result) map[string]Status {
	byID := map[string]Status{}
	for _, result := range results {
		byID[result.ID] = result.Status
	}
	return byID
}

func TestUpgradeV020ProjectIsCompleteAndIdempotent(t *testing.T) {
	project := v020Project(t)
	results, err := Plan(project, "v1.1.0")
	if err != nil {
		t.Fatal(err)
	}
	for id, status := range statuses(results) {
		if status != StatusPending {
			t.Errorf("%s = %s, want pending", id, status)
		}
	}
	if err := Apply(project, results); err != nil {
		t.Fatal(err)
	}

	gitignore, _ := os.ReadFile(filepath.Join(project, ".gitignore"))
	if !strings.Contains(string(gitignore), "\n/config.yml\n") {
		t.Errorf(".gitignore still indented:\n%s", gitignore)
	}
	database, _ := os.ReadFile(filepath.Join(project, "databases", "pg.go"))
	if strings.Contains(string(database), "panic(") || !strings.Contains(string(database), "func ConnectDB() (*gorm.DB, error) {") {
		t.Errorf("ConnectDB not upgraded:\n%s", database)
	}
	main, _ := os.ReadFile(filepath.Join(project, "main.go"))
	if !strings.Contains(string(main), "conn, err := databases.ConnectDB()") || !strings.Contains(string(main), `log.Fatalf("failed to start: %v", err)`) {
		t.Errorf("main.go not upgraded:\n%s", main)
	}
	manifest, err := generator.ReadProjectManifest(project)
	if err != nil {
		t.Fatal(err)
	}
	if manifest != (generator.ProjectManifest{GOTVersion: "v1.1.0", Module: "example.com/shop", Architecture: "microservice", Database: "pg"}) {
		t.Errorf("manifest = %+v", manifest)
	}

	again, err := Plan(project, "v1.1.0")
	if err != nil {
		t.Fatal(err)
	}
	for id, status := range statuses(again) {
		if status != StatusUpToDate {
			t.Errorf("second run: %s = %s, want up-to-date", id, status)
		}
	}
}

func TestUpgradeLeavesCustomizedCodeForTheDeveloper(t *testing.T) {
	project := v020Project(t)
	path := filepath.Join(project, "databases", "pg.go")
	content, _ := os.ReadFile(path)
	customized := strings.Replace(string(content), "panic(err)", "panic(fmt.Errorf(\"db: %w\", err))", 1)
	if err := os.WriteFile(path, []byte(customized), 0o644); err != nil {
		t.Fatal(err)
	}
	results, err := Plan(project, "v1.1.0")
	if err != nil {
		t.Fatal(err)
	}
	for _, result := range results {
		if result.ID != "database-connect-error" {
			continue
		}
		if result.Status != StatusManual || len(result.Changes) != 0 || !strings.Contains(result.Detail, "log.Fatalf") {
			t.Fatalf("customized ConnectDB: %+v", result)
		}
	}
	if err := Apply(project, results); err != nil {
		t.Fatal(err)
	}
	after, _ := os.ReadFile(path)
	if string(after) != customized {
		t.Fatal("upgrade modified customized code")
	}
	main, _ := os.ReadFile(filepath.Join(project, "main.go"))
	if strings.Contains(string(main), "conn, err := databases.ConnectDB()") {
		t.Fatal("main.go was changed although its database step was manual")
	}
}

func TestUpgradeManifestVersionTracking(t *testing.T) {
	project := v020Project(t)
	manifest, _ := generator.EncodeProjectManifest(generator.ProjectManifest{GOTVersion: "v1.0.4", Module: "example.com/shop", Architecture: "microservice", Database: "pg"})
	if err := os.WriteFile(filepath.Join(project, generator.ProjectManifestName), manifest, 0o644); err != nil {
		t.Fatal(err)
	}
	for version, want := range map[string]Status{"v1.0.4": StatusUpToDate, "dev": StatusUpToDate, "v1.1.0": StatusPending} {
		results, err := Plan(project, version)
		if err != nil {
			t.Fatal(err)
		}
		if got := statuses(results)["project-manifest"]; got != want {
			t.Errorf("version %s: project-manifest = %s, want %s", version, got, want)
		}
	}
}
